# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Chebyshev polynomial of the fourth kind, W_n(x), elementwise.

Reference semantics (verified against torch.special.chebyshev_polynomial_w):
    W_0(x) = 1
    W_1(x) = 2x + 1
    W_k(x) = 2x * W_{k-1}(x) - W_{k-2}(x)
with the degree truncated toward zero (m = int(n)); m < 0 yields 0, and any
input whose dtype is not float32/float64 is rejected, because ATen only
dispatches floating types for this operator.

Design notes:
  * one flat 1-D grid-strided launch per call (the GCU caps grid.x at 65535,
    so large tensors are covered with a uniform per-program chunk loop),
    computed in the input's own precision;
  * three specializations chosen from cheap metadata only:
        N_MODE 0 : host-known Python scalar degree (no degree load),
        N_MODE 1 : single-element degree tensor (scalar load, uniform bound),
        N_MODE 2 : per-element degree tensor (tile max bound + per-lane mask);
  * a strided fallback covers non-contiguous / broadcasting inputs;
  * no framework arithmetic produces the result and no input is mutated.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_BLOCK = 1024
_NUM_WARPS = 1
_MAX_GRID = 65535
_BIG_TOTAL = 1 << 20
# 大 shape 用 8192 的 fat tile 打满 DTE；中小 shape 保持 1024：
# 实测更细的 256 tile 会让高阶动态递推 miscompile，2048 tile 令 96k shape 劣化 36%。
# 16384 配 num_warps=1 在本工具链会编译失败（PassManager），故上限取 8192。
_TILE_BIG = 8192
# GCU400 的 SIP 拓扑对应 24 个物理 SIP；48 个 CTA 是持久网格的经验上限，
# 更多 CTA 只会增加调度成本（每个 CTA 约 0.46us），核内用跨步循环补齐 tile。
_GRID_SIPS = 48

# Safety cap for data-dependent loop bounds (tested degrees are tiny).
_MAX_STEPS = tl.constexpr(1024)
# 常见阶数在编译期展开：避免 degree 来自设备标量时循环上界无法静态展开。
_UNROLL_ORDER = tl.constexpr(3)


def _pick(numel):
    """(BLOCK, grid.x) for a launch over `numel` elements.

    仅大 shape 换用 fat tile；grid 固定不超过 _GRID_SIPS，剩余 tile 由 kernel
    内的跨步循环消费，num_programs 只影响运行时跨步长度。
    """
    block = _BLOCK if numel < _BIG_TOTAL else _TILE_BIG
    grid = min((numel + block - 1) // block, _GRID_SIPS)
    return block, grid


@triton.jit(do_not_specialize=["numel", "degree"])
def _w_flat_kernel(
    X,
    N,
    OUT,
    numel,
    degree,
    N_MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    nchunk = tl.cdiv(numel, step)
    start0 = pid * BLOCK
    rng = tl.arange(0, BLOCK)

    for c in range(0, nchunk):
        offs = start0 + c * step + rng
        mask = offs < numel
        x = tl.load(X + offs, mask=mask, other=0.0)
        # 0 与 2 用标量常量直接广播，只保留递推初值所需的向量 1。
        zero = 0.0
        one = tl.full((BLOCK,), 1.0, x.dtype)
        two = 2.0

        if N_MODE == 2:
            # Per-element degrees: bound the loop by the tile maximum.
            m = tl.load(N + offs, mask=mask, other=0).to(tl.int32)
            steps = tl.minimum(
                tl.maximum(tl.max(tl.where(mask, m, 0), axis=0), 0), _MAX_STEPS
            )
            w0 = one
            w1 = two * x + one
            for k in range(2, steps + 1):
                w2 = two * x * w1 - w0
                act = m >= k
                w0 = tl.where(act, w1, w0)
                w1 = tl.where(act, w2, w1)
            res = tl.where(m < 0, zero, tl.where(m == 0, one, w1))
        else:
            if N_MODE == 1:
                # One degree for the whole launch (0-dim / 1-element tensor).
                m = tl.load(N).to(tl.int32)
            else:
                # Host-known degree.
                m = degree
            steps = tl.minimum(tl.maximum(m, 0), _MAX_STEPS)
            w0 = one
            w1 = two * x + one
            # 常见阶数编译期展开：degree 是设备标量时循环上界无法静态展开，
            # 这里固定展开 _UNROLL_ORDER 步，用 active 掩码屏蔽多余的递推。
            for k in tl.static_range(2, _UNROLL_ORDER + 1):
                w2 = two * x * w1 - w0
                active = steps >= k
                w0 = tl.where(active, w1, w0)
                w1 = tl.where(active, w2, w1)
            # 超过展开上限的阶数仍按动态循环补齐，保持任意阶语义。
            for k in range(_UNROLL_ORDER + 1, steps + 1):
                w2 = two * x * w1 - w0
                w0 = w1
                w1 = w2
            res = tl.where(m < 0, zero, tl.where(m == 0, one, w1))

        tl.store(OUT + offs, res, mask=mask)


@triton.jit
def _w_strided_kernel(
    X,
    N,
    OUT,
    numel,
    degree,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xs6,
    xs7,
    ns0,
    ns1,
    ns2,
    ns3,
    ns4,
    ns5,
    ns6,
    ns7,
    N_MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    nchunk = tl.cdiv(numel, step)
    start0 = pid * BLOCK
    rng = tl.arange(0, BLOCK)

    dims = (d0, d1, d2, d3, d4, d5, d6, d7)
    xstr = (xs0, xs1, xs2, xs3, xs4, xs5, xs6, xs7)
    nstr = (ns0, ns1, ns2, ns3, ns4, ns5, ns6, ns7)

    for c in range(0, nchunk):
        offs = start0 + c * step + rng
        mask = offs < numel

        rem = offs
        xoff = tl.zeros((BLOCK,), tl.int32)
        noff = tl.zeros((BLOCK,), tl.int32)
        for i in range(7, -1, -1):
            d = tl.where(dims[i] > 0, dims[i], 1)
            cc = rem % d
            rem = rem // d
            xoff += cc * xstr[i]
            noff += cc * nstr[i]

        x = tl.load(X + xoff, mask=mask, other=0.0)
        # 0 与 2 用标量常量直接广播，只保留递推初值所需的向量 1。
        zero = 0.0
        one = tl.full((BLOCK,), 1.0, x.dtype)
        two = 2.0

        if N_MODE == 2:
            m = tl.load(N + noff, mask=mask, other=0).to(tl.int32)
            steps = tl.minimum(
                tl.maximum(tl.max(tl.where(mask, m, 0), axis=0), 0), _MAX_STEPS
            )
            w0 = one
            w1 = two * x + one
            for k in range(2, steps + 1):
                w2 = two * x * w1 - w0
                act = m >= k
                w0 = tl.where(act, w1, w0)
                w1 = tl.where(act, w2, w1)
            res = tl.where(m < 0, zero, tl.where(m == 0, one, w1))
        else:
            if N_MODE == 1:
                m = tl.load(N).to(tl.int32)
            else:
                m = degree
            steps = tl.minimum(tl.maximum(m, 0), _MAX_STEPS)
            w0 = one
            w1 = two * x + one
            for k in range(2, steps + 1):
                w2 = two * x * w1 - w0
                w0 = w1
                w1 = w2
            res = tl.where(m < 0, zero, tl.where(m == 0, one, w1))

        tl.store(OUT + offs, res, mask=mask)


_DIMS = 8


def _strided_launch(x, n, out, numel, degree, n_mode, block, warps):
    """General (non-contiguous / broadcasting) fallback."""
    shape = out.shape
    nd = len(shape)
    if nd > _DIMS:
        raise ValueError("special_chebyshev_polynomial_w: too many dimensions")
    pad = _DIMS - nd
    dims = [1] * pad + [int(s) for s in shape]
    xs = [0] * pad + [int(s) for s in x.stride()]
    ns = [0] * pad + [int(s) for s in n.stride()]
    grid = (min((numel + block - 1) // block, _MAX_GRID),)
    _w_strided_kernel[grid](
        x,
        n,
        out,
        numel,
        degree,
        *dims,
        *xs,
        *ns,
        N_MODE=n_mode,
        BLOCK=block,
        num_warps=warps,
    )


def _run(x, n, out=None):
    dtype = x.dtype
    if dtype is not torch.float32 and dtype is not torch.float64:
        raise ValueError(
            "special_chebyshev_polynomial_w only supports float32/float64, "
            f"got {dtype}"
        )

    if out is not None and not out.is_contiguous():
        # The kernels store with linear offsets; use a contiguous scratch buffer
        # and copy the result back into the caller's tensor.
        out.copy_(_run(x, n))
        return out

    numel = x.numel()
    if out is None:
        out = torch.empty(x.shape, dtype=dtype, device=x.device)

    if numel == 0:
        return out

    block, grid_n = _pick(numel)
    warps = _NUM_WARPS
    grid = (grid_n,)

    if isinstance(n, torch.Tensor):
        if n.dtype is torch.int64:
            # 64-bit data is not accepted by every backend's kernels; narrow the
            # degree to int32 (the recurrence stays far below its range).
            n = n.to(torch.int32)
        if n.numel() == 1:
            n_mode = 1
        else:
            n_mode = 2
            # NOTE: the per-lane-degree kernel does not compile with the fat
            # tile or with num_warps=1 here ("64-bit data type not supported on
            # GCU300"), so that path keeps the original geometry.
            block = _BLOCK
            grid = (min(triton.cdiv(numel, _BLOCK), _MAX_GRID),)
            warps = 4
        if n_mode == 1 and x.is_contiguous():
            _w_flat_kernel[grid](
                x, n, out, numel, 0, N_MODE=1, BLOCK=block, num_warps=warps
            )
        elif n_mode == 2 and x.is_contiguous() and n.is_contiguous():
            _w_flat_kernel[grid](
                x, n, out, numel, 0, N_MODE=2, BLOCK=block, num_warps=warps
            )
        else:
            xb = x if x.shape == out.shape else x.expand(out.shape)
            nb = n if n.shape == out.shape else n.expand(out.shape)
            # same restriction as the flat path: N_MODE=2 only compiles with
            # the small tile and four warps.
            _strided_launch(
                xb,
                nb,
                out,
                numel,
                0,
                n_mode,
                _BLOCK if n_mode == 2 else block,
                4 if n_mode == 2 else warps,
            )
    else:
        degree = int(n)
        if x.is_contiguous():
            _w_flat_kernel[grid](
                x, x, out, numel, degree, N_MODE=0, BLOCK=block, num_warps=warps
            )
        else:
            _strided_launch(x, x, out, numel, degree, 0, block, warps)

    return out


def special_chebyshev_polynomial_w(x, n):
    logger.debug("GEMS_ENFLAME_GCU400 SPECIAL_CHEBYSHEV_POLYNOMIAL_W")
    return _run(x, n)


def special_chebyshev_polynomial_w_out(x, n, out):
    """Out-of-place variant for special_chebyshev_polynomial_w.

    ATen wrapper: special_chebyshev_polynomial_w.out(Tensor x, Scalar n, *, Tensor(a!) out) -> Tensor(a!)
    """
    logger.debug("GEMS_ENFLAME_GCU400 SPECIAL_CHEBYSHEV_POLYNOMIAL_W_OUT")
    return _run(x, n, out)
